const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const reportDate = input.report_date || new Date().toISOString().slice(0, 10);
const timezone = input.timezone || 'America/Bogota';

// 1. Data Quality Checks (null != 0 rule, SOURCE_UNAVAILABLE handling)
const finStatus = input.financial_source_status || 'AVAILABLE';
const okvetStatus = input.okvet_sync_status || 'SYNCED';

const isFinAvailable = finStatus !== 'SOURCE_UNAVAILABLE';
const revVerified = isFinAvailable ? Number(input.yesterday_revenue_cop || 0) : null;
const revUnverified = isFinAvailable ? Number(input.unverified_payments_cop || 0) : null;
const revFmt = isFinAvailable 
  ? '$' + revVerified.toLocaleString('es-CO') + ' COP' 
  : '[FUENTE FINANCIERA INDISPONIBLE]';

// 2. Exception & Alert Detection
const alerts = [];
let alertLevel = 'INFORMATIONAL'; // INFORMATIONAL, OPERATIONAL_ATTENTION, HIGH_PRIORITY, CRITICAL_OPERATIONAL

if (!isFinAvailable) {
  alerts.push({ level: 'HIGH_PRIORITY', domain: 'FINANCES', message: 'Pasarela de pagos o extracto bancario no disponible para conciliación.' });
  alertLevel = 'HIGH_PRIORITY';
}
if ((input.uncovered_shifts_count || 0) > 0) {
  alerts.push({ level: 'CRITICAL_OPERATIONAL', domain: 'STAFF', message: `${input.uncovered_shifts_count} turno(s) sin cobertura veterinaria.` });
  alertLevel = 'CRITICAL_OPERATIONAL';
}
if ((input.delays_documented_count || 0) > 1) {
  alerts.push({ level: 'OPERATIONAL_ATTENTION', domain: 'ROUTES', message: `${input.delays_documented_count} retrasos significativos en rutas reportados.` });
  if (alertLevel !== 'CRITICAL_OPERATIONAL') alertLevel = 'OPERATIONAL_ATTENTION';
}
if ((input.open_complaints_count || 0) > 0) {
  alerts.push({ level: 'HIGH_PRIORITY', domain: 'EXPERIENCE', message: `${input.open_complaints_count} reclamación(es) o insatisfacción(es) activa(s).` });
  if (alertLevel !== 'CRITICAL_OPERATIONAL') alertLevel = 'HIGH_PRIORITY';
}
if ((input.overdue_commitments_count || 0) > 0) {
  alerts.push({ level: 'OPERATIONAL_ATTENTION', domain: 'POST_VISIT', message: `${input.overdue_commitments_count} compromiso(s) post-visita vencido(s).` });
  if (alertLevel === 'INFORMATIONAL') alertLevel = 'OPERATIONAL_ATTENTION';
}
if ((input.pending_triage_count || 0) > 0) {
  alerts.push({ level: 'OPERATIONAL_ATTENTION', domain: 'APPOINTMENTS', message: `${input.pending_triage_count} solicitud(es) de triage pendientes.` });
  if (alertLevel === 'INFORMATIONAL') alertLevel = 'OPERATIONAL_ATTENTION';
}

const requiresAttention = alertLevel !== 'INFORMATIONAL';
const trafficLight = alertLevel === 'CRITICAL_OPERATIONAL' ? 'ROJO 🔴' : (alertLevel === 'HIGH_PRIORITY' ? 'AMARILLO 🟡' : (alertLevel === 'OPERATIONAL_ATTENTION' ? 'AMARILLO 🟡' : 'VERDE 🟢'));

// 3. Decisions for Dr. Luis vs Smart Delegation
const decisionsForLuis = [];
if (!isFinAvailable) {
  decisionsForLuis.push({
    decision: 'Aprobación de conciliación manual por contingencia bancaria',
    recommendation: 'Autorizar a contabilidad verificación de extractos PDF',
    deadline: '10:00 AM'
  });
}
if ((input.uncovered_shifts_count || 0) > 0) {
  decisionsForLuis.push({
    decision: 'Reasignación de rutas por turno sin cobertura',
    recommendation: 'Activar veterinario de contingencia o reprogramar 2 visitas no urgentes',
    deadline: '07:30 AM'
  });
}

const delegatedActions = [
  { assignee: 'Coordinación Operativa', action: 'Monitoreo de salida puntual en rutas Bogotá Norte y Sur (08:00 AM)' },
  { assignee: 'Médicos Veterinarios de Ruta', action: 'Cierre clínico síncrono en OKVET antes de salida de cada domicilio' },
  { assignee: 'Administración / Facturación', action: `Conciliar ${input.unverified_payments_count || 0} transferencias pendientes por $${Number(input.unverified_payments_cop || 0).toLocaleString('es-CO')} COP` }
];

// 4. Priorities for Tomorrow (Fact-based)
const prioritiesTomorrow = [
  'Garantizar cobertura y kit de insumos para las visitas programadas',
  'Seguimiento a las remisiones de especialistas coordinadas',
  'Verificación de cierre de compromisos post-visita en 24h'
];

// 5. 60-Second Executive Summary ("Visión de 60 segundos")
const summary60s = 
`=====================================================
🐾 VET FREEDOM OS — VISIÓN EJECUTIVA (60 SEGUNDOS)
Dr. Luis Eduardo Ríos | Vet Life — Veterinaria a Domicilio
Fecha: ${reportDate} | Zona: ${timezone} | Estado: ${trafficLight}
=====================================================

1. TITULAR DEL DÍA:
   ${trafficLight} - ${requiresAttention ? 'Atención operativa requerida en ' + alerts.map(a => a.domain).join(', ') : 'Operación normal y alineada con metas clínicas y comerciales.'}

2. ALERTAS & EXCEPCIONES (${alerts.length}):
${alerts.length > 0 ? alerts.map(a => `   • [${a.level}] ${a.message}`).join('\n') : '   • Ninguna alerta crítica activa. Indicadores dentro de límites normales.'}

3. DECISIONES RESERVADAS PARA EL DR. LUIS (${decisionsForLuis.length}):
${decisionsForLuis.length > 0 ? decisionsForLuis.map(d => `   • ${d.decision} -> Plazo: ${d.deadline} (Recomendación: ${d.recommendation})`).join('\n') : '   • Ninguna decisión bloqueante requerida en este momento.'}

4. DELEGACIÓN INTELIGENTE:
${delegatedActions.map(da => `   • [${da.assignee}] ${da.action}`).join('\n')}

5. BALANCE OPERATIVO Y FINANCIERO:
   • Visitas programadas / ejecutadas: ${input.scheduled_visits_count || 0} / ${input.completed_visits_count || 0}
   • Veterinarios activos en ruta: ${input.vets_on_duty_count || 0} (Ausencias: ${input.active_absences_count || 0})
   • Recaudo verificado: ${revFmt}
   • Pagos pendientes de verificación: $${Number(input.unverified_payments_cop || 0).toLocaleString('es-CO')} COP (${input.unverified_payments_count || 0} transacciones)
   • Remisiones a especialistas: ${input.pending_referrals_count || 0} en curso
   • Compromisos post-visita abiertos: ${input.open_commitments_count || 0} (Vencidos: ${input.overdue_commitments_count || 0})

6. PRIORIDADES CLAVE:
${prioritiesTomorrow.map(p => `   • ${p}`).join('\n')}

=====================================================
[MODO SEGURO QA ACTIVO: 0 envíos reales a tutores ni médicos]`;

return {
  json: {
    report_date: reportDate,
    timezone: timezone,
    traffic_light: trafficLight,
    alert_level: alertLevel,
    requires_attention: requiresAttention,
    summary_60s: summary60s,
    alerts: alerts,
    decisions_for_luis: decisionsForLuis,
    delegated_actions: delegatedActions,
    priorities_tomorrow: prioritiesTomorrow,
    metrics: {
      appointments: {
        scheduled: input.scheduled_visits_count || 0,
        pending_triage: input.pending_triage_count || 0
      },
      visits: {
        completed: input.completed_visits_count || 0,
        in_progress: ((input.scheduled_visits_count || 0) - (input.completed_visits_count || 0)) > 0 ? 1 : 0
      },
      staff: {
        vets_on_duty: input.vets_on_duty_count || 0,
        active_absences: input.active_absences_count || 0,
        uncovered_shifts: input.uncovered_shifts_count || 0
      },
      routes: {
        active_routes: input.active_routes_count || 0,
        delays_documented: input.delays_documented_count || 0
      },
      finances: {
        verified_revenue_cop: revVerified,
        unverified_revenue_cop: revUnverified,
        unverified_count: input.unverified_payments_count || 0,
        source_status: finStatus,
        quality_state: isFinAvailable ? 'VERIFIED' : 'SOURCE_UNAVAILABLE'
      },
      experience: {
        open_complaints: input.open_complaints_count || 0
      },
      post_visit: {
        open_commitments: input.open_commitments_count || 0,
        overdue_commitments: input.overdue_commitments_count || 0
      },
      specialists: {
        pending_referrals: input.pending_referrals_count || 0
      },
      integrations: {
        okvet_sync: okvetStatus,
        supabase_status: 'HEALTHY'
      }
    },
    safe_mode: {
      send_enabled: false,
      active: false,
      environment: 'DEVELOPMENT/QA'
    },
    generated_at: new Date().toISOString()
  }
};
